#include <iostream>
using namespace std;

int main() {
    int x = 10;

    // Without mutable: x inside lambda is const -- cannot modify
    // auto f = [x]() { x++; }; // ERROR

    // With mutable: OK to modify the lambda's internal copy
    auto counter = [x]() mutable {
        return ++x; // modifies lambda's copy, not outer x
    };
    cout << counter() << endl; // 11
    cout << counter() << endl; // 12
    cout << x << endl;         // still 10!

    // Initialized capture (C++14)
    auto gen = [n = 0]() mutable { return n++; };
    cout << gen() << endl; // 0
    cout << gen() << endl; // 1
    return 0;
}

